"""Within-topology Spearman ρ(F1, |bias|) analysis.

Computes per-topology and overall Spearman rank correlations between
macro F1 and |bias| across all 161 empirical scenarios (23 configs × 7 topologies).
"""

import json
import numpy as np
from pathlib import Path
from scipy import stats as sp_stats

PROJ = Path(__file__).resolve().parent.parent
OUT = PROJ / "artifacts" / "within_topo_f1_bias_results.json"

TOPOLOGIES = ["confounding", "mediation", "collider", "exposure",
              "mbias", "frontdoor", "iv"]


def make_p_A(K):
    if K == 2:
        return np.array([0.55, 0.45])
    elif K == 3:
        return np.array([0.40, 0.35, 0.25])
    else:
        raw = np.array([1.0 / (i + 1) for i in range(K)])
        return raw / raw.sum()


def compute_f1_from_C(C, K, p_A):
    C = np.asarray(C)
    precision = np.zeros(K)
    recall = np.zeros(K)
    f1 = np.zeros(K)
    for i in range(K):
        recall[i] = C[i, i]
        denom = sum(C[i, j] * p_A[j] for j in range(K))
        precision[i] = C[i, i] * p_A[i] / denom if denom > 1e-12 else 0
        if precision[i] + recall[i] > 1e-12:
            f1[i] = 2 * precision[i] * recall[i] / (precision[i] + recall[i])
    return float(f1.mean())


def main():
    with open(PROJ / "artifacts" / "updated_empirical_results.json") as f:
        data = json.load(f)

    cms = data["confusion_matrices"]
    biases = data["biases"]

    config_f1 = {}
    for config_name, C_list in cms.items():
        K = len(C_list)
        p_A = make_p_A(K)
        config_f1[config_name] = compute_f1_from_C(C_list, K, p_A)

    rows = []
    for b in biases:
        config_name = f"{b['dataset']}_{b['model']}_{b['prompt']}"
        if config_name not in config_f1:
            continue
        if b["bias"] is None:
            continue
        rows.append({
            "config": config_name,
            "dataset": b["dataset"],
            "topology": b["topology"],
            "macro_f1": config_f1[config_name],
            "abs_bias": abs(b["bias"]),
        })

    # Per-topology Spearman ρ
    per_topo = {}
    for topo in TOPOLOGIES:
        subset = [r for r in rows if r["topology"] == topo]
        if len(subset) < 3:
            per_topo[topo] = {"n": len(subset), "rho": None, "p": None}
            continue
        f1s = [r["macro_f1"] for r in subset]
        abs_biases = [r["abs_bias"] for r in subset]
        rho, p = sp_stats.spearmanr(f1s, abs_biases)
        per_topo[topo] = {
            "n": len(subset),
            "rho": round(float(rho), 4),
            "p": round(float(p), 4),
            "f1_range": [round(min(f1s), 4), round(max(f1s), 4)],
            "abs_bias_range": [round(min(abs_biases), 4), round(max(abs_biases), 4)],
        }

    # Per-dataset per-topology
    per_ds_topo = {}
    for ds in sorted(set(r["dataset"] for r in rows)):
        per_ds_topo[ds] = {}
        for topo in TOPOLOGIES:
            subset = [r for r in rows if r["dataset"] == ds and r["topology"] == topo]
            if len(subset) < 3:
                per_ds_topo[ds][topo] = {"n": len(subset), "rho": None, "p": None}
                continue
            f1s = [r["macro_f1"] for r in subset]
            abs_biases = [r["abs_bias"] for r in subset]
            rho, p = sp_stats.spearmanr(f1s, abs_biases)
            per_ds_topo[ds][topo] = {
                "n": len(subset),
                "rho": round(float(rho), 4),
                "p": round(float(p), 4),
            }

    # Overall Spearman ρ
    all_f1 = [r["macro_f1"] for r in rows]
    all_abs_bias = [r["abs_bias"] for r in rows]
    rho_all, p_all = sp_stats.spearmanr(all_f1, all_abs_bias)

    # Per-dataset overall
    per_ds_overall = {}
    for ds in sorted(set(r["dataset"] for r in rows)):
        subset = [r for r in rows if r["dataset"] == ds]
        f1s = [r["macro_f1"] for r in subset]
        abs_biases = [r["abs_bias"] for r in subset]
        rho, p = sp_stats.spearmanr(f1s, abs_biases)
        per_ds_overall[ds] = {
            "n": len(subset),
            "rho": round(float(rho), 4),
            "p": round(float(p), 4),
        }

    result = {
        "meta": {
            "description": "Within-topology Spearman rho(macro_F1, |bias|)",
            "n_total": len(rows),
            "n_configs": len(config_f1),
            "n_topologies": len(TOPOLOGIES),
        },
        "overall": {
            "rho": round(float(rho_all), 4),
            "p": round(float(p_all), 4),
            "n": len(rows),
        },
        "per_dataset_overall": per_ds_overall,
        "per_topology": per_topo,
        "per_dataset_topology": per_ds_topo,
    }

    with open(OUT, "w") as f:
        json.dump(result, f, indent=2)

    print(f"Total scenarios: {len(rows)}")
    print(f"\nOverall: ρ={rho_all:.4f}, p={p_all:.4f}, n={len(rows)}")
    print(f"\nPer-dataset overall:")
    for ds, v in per_ds_overall.items():
        print(f"  {ds}: ρ={v['rho']:.4f}, p={v['p']:.4f}, n={v['n']}")
    print(f"\nPer-topology (all datasets):")
    for topo in TOPOLOGIES:
        t = per_topo[topo]
        if t["rho"] is not None:
            print(f"  {topo:12s}: ρ={t['rho']:+.4f}, p={t['p']:.4f}, n={t['n']}")
        else:
            print(f"  {topo:12s}: insufficient data (n={t['n']})")
    print(f"\nResults saved to {OUT}")


if __name__ == "__main__":
    main()

